-- Facilities catalog (seeded from app data) and custom hospital location fields

CREATE TABLE IF NOT EXISTS facilities (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  type TEXT NOT NULL CHECK (type IN ('hospital', 'blood_bank')),
  city TEXT NOT NULL,
  address TEXT NOT NULL,
  latitude DOUBLE PRECISION NOT NULL,
  longitude DOUBLE PRECISION NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_facilities_city ON facilities(city);
CREATE INDEX IF NOT EXISTS idx_facilities_type ON facilities(type);
CREATE INDEX IF NOT EXISTS idx_facilities_name ON facilities(name);

ALTER TABLE blood_requests
  ADD COLUMN IF NOT EXISTS facility_id TEXT REFERENCES facilities(id),
  ADD COLUMN IF NOT EXISTS custom_hospital_name TEXT,
  ADD COLUMN IF NOT EXISTS pincode TEXT,
  ADD COLUMN IF NOT EXISTS location_district TEXT,
  ADD COLUMN IF NOT EXISTS location_state TEXT;

ON CONFLICT (id) DO NOTHING;
